function Nx.ModQuests:Load5()
    local ModQuests = Nx.ModQuests:Data5()
    local count = 0
    for key, val in pairs(ModQuests) do
        Nx.Quests[key] = val
        count = count + 1
    end
    ModQuests = {}
    return count
end

function Nx.ModQuests:Clear5()
    --ModQuests = {}
end
